// What the Blender MODEL of a building says about it, beyond its picture:
// where its entrance is and which parts of it move.
//
// The two maps at the bottom are GENERATED by tool/blender/make_building.py
// (one line per building, rewritten in place on every render). Do not edit
// those lines by hand — change the model and re-render. The types above them
// are hand-written.
library;

/// How one animated layer moves (user 2026-11-03: "Kleider wiegen sich im
/// Wind, Blumen wanken, Licht flackert von einer Kerze").
enum AnimKind {
  /// Leans about [BuildingAnimLayer.px]/[BuildingAnimLayer.py]: a horizontal
  /// shear that is zero on the pivot's line and grows away from it — washing
  /// hanging from a line (pivot on top), flowers and bushes (pivot at the
  /// ground).
  sway,

  /// Bobs up and down — a floating mote, a bird on a ridge.
  bob,

  /// Extra light added over the picture, breathing slowly — lit windows.
  glow,

  /// Extra light, restless and quick — a candle, a lantern, a fire.
  flicker,
}

/// One moving part, cut out of the building's render.
///
/// Every number is relative so the layer lands on the picture at any decode
/// size: the SOURCE rect is in the atlas's own pixels, the DESTINATION rect
/// and the pivot in fractions of the building's base picture (x of its width,
/// y of its height, from the top-left).
class BuildingAnimLayer {
  final AnimKind kind;
  final double sx, sy, sw, sh;
  final double l, t, w, h;
  final double px, py;

  /// sway: shear at full swing (0.1 = a tenth of the height above/below the
  /// pivot). bob: travel as a fraction of the picture's width. glow/flicker:
  /// peak extra opacity.
  final double amp;

  /// Seconds for one full swing/breath.
  final double period;

  /// 0..2π, so the parts of one building do not move in step.
  final double phase;

  const BuildingAnimLayer(
    this.kind,
    this.sx,
    this.sy,
    this.sw,
    this.sh,
    this.l,
    this.t,
    this.w,
    this.h,
    this.px,
    this.py,
    this.amp,
    this.period,
    this.phase,
  );
}

class BuildingAnimSpec {
  /// The base picture's height / width.
  final double aspect;

  /// Whether `<id>_base.webp` ships: the picture with every SWAYING part cut
  /// out (the map draws those parts itself, moving). False when the building
  /// only has light layers — then the ordinary `<id>.webp` is the base.
  final bool hasBase;

  final List<BuildingAnimLayer> layers;

  const BuildingAnimSpec(this.aspect, this.hasBase, this.layers);

  String baseAsset(String id) => hasBase
      ? 'assets/images/buildings/${id}_base.webp'
      : 'assets/images/buildings/$id.webp';

  static String atlasAsset(String id) =>
      'assets/images/buildings/${id}_anim.webp';
}

/// A building's ENTRANCE (user 2026-11-03): one cell of its footprint, and
/// the direction its door path leaves it in. The cell OUTSIDE it in that
/// direction is where a road has to lie for the building to count as
/// connected — see GameEngine.connectedBuildingIds.
///
/// (cx, cy) is the cell, relative to the footprint's top-left (grid x, y);
/// (dx, dy) is one of (1,0), (-1,0), (0,1), (0,-1).
typedef BuildingEntrance = (int cx, int cy, int dx, int dy);

/// The road cell in front of [e] for a building whose footprint starts at
/// (gx, gy).
(int, int) entranceRoadCell(BuildingEntrance e, int gx, int gy) =>
    (gx + e.$1 + e.$3, gy + e.$2 + e.$4);

/// The entrance of building [id] — but only while the def's footprint is the
/// one the model was built for. The defs come from the DATABASE, and a row
/// that still carries an old footprint (the live Small House was 3x3 while
/// its new model is 2x2, 2026-11-03) would put the entrance in the middle of
/// the building; until its migration has run it keeps the old any-side rule.
BuildingEntrance? entranceFor(String id, int gridW, int gridH) =>
    _modelFits(id, gridW, gridH) ? kBuildingEntrance[id] : null;

/// The moving parts of [id], under the same footprint guard as
/// [entranceFor] — the layers are cut to the model's own picture.
BuildingAnimSpec? animFor(String id, int gridW, int gridH) =>
    _modelFits(id, gridW, gridH) ? kBuildingAnim[id] : null;

bool _modelFits(String id, int w, int h) {
  final f = kModelFootprint[id];
  return f == null || (f.$1 == w && f.$2 == h);
}

